WITH "authorized_Deck" AS NOT MATERIALIZED (SELECT "root"."id" AS "id" FROM "Deck" "leaf" JOIN "Entity" "root" ON "root"."id" = "leaf"."id"),
"authorized_Printing" AS NOT MATERIALIZED (SELECT "leaf"."card.id" AS "card.id", NULL AS "deck.id", "root"."entity" AS "entity", "root"."id" AS "id", "root"."name" AS "name" FROM "Printing" "leaf" JOIN "Entity" "root" ON "root"."id" = "leaf"."id"),
"authorized_Face" AS NOT MATERIALIZED (SELECT "leaf"."card.id" AS "card.id", "root"."entity" AS "entity", "root"."id" AS "id", "root"."name" AS "name" FROM "Face" "leaf" JOIN "Entity" "root" ON "root"."id" = "leaf"."id"),
"batch_selected_rows_0" AS MATERIALIZED ( SELECT "t".* FROM "authorized_Deck" "t"    LIMIT $1 OFFSET $2 ),
"batch_selected_roots_1" AS MATERIALIZED ( SELECT "t"."id" AS "id"  FROM "batch_selected_rows_0" "t" ),
"batch_source_2" AS MATERIALIZED (SELECT "cj3"."deck.id" AS "__parent_id", "cj3".* FROM "DeckPrinting" "cj3" JOIN "batch_selected_roots_1" "t" ON TRUE WHERE "cj3"."deck.id" = "t"."id"),
"flat_targets_fb4" AS MATERIALIZED (SELECT "ct1".* FROM "authorized_Printing" "ct1" WHERE "ct1"."id" IN (SELECT "__edge_row"."printing.id" FROM "batch_source_2" AS "__edge_row")),
"flat_base_fb4" AS MATERIALIZED (SELECT "__edge_row"."__parent_id", "ct1"."id" AS "__item_id", "ct1".* FROM "batch_source_2" AS "__edge_row" JOIN "flat_targets_fb4" "ct1" ON "ct1"."id" = "__edge_row"."printing.id"),
"flat_scope_ids_fb4" AS MATERIALIZED (SELECT "__parent_id", "__item_id", row_number() OVER (PARTITION BY "__parent_id" ORDER BY "__item_id") AS "__ordinal" FROM (SELECT DISTINCT "__parent_id", "__item_id" FROM "flat_base_fb4" ) AS "__identity"),
"flat_scope_fb4" AS MATERIALIZED (SELECT DISTINCT ON ("flat_base_fb4"."__parent_id", "flat_base_fb4"."__item_id") "flat_base_fb4".*, "flat_scope_ids_fb4"."__ordinal" FROM "flat_base_fb4" JOIN "flat_scope_ids_fb4" ON "flat_scope_ids_fb4"."__parent_id" = "flat_base_fb4"."__parent_id" AND "flat_scope_ids_fb4"."__item_id" = "flat_base_fb4"."__item_id" WHERE "flat_scope_ids_fb4"."__ordinal" -  $3  BETWEEN 1 AND  $4),
"batch_child_roots_flat_3" AS MATERIALIZED (SELECT DISTINCT "id" FROM "flat_scope_fb4"),
"reachable_Card_0" AS MATERIALIZED (SELECT "root"."entity" AS "entity", "root"."id" AS "id", "root"."name" AS "name" FROM "Card" "leaf" JOIN "Entity" "root" ON "root"."id" = "leaf"."id" WHERE "leaf"."id" IN (SELECT "card.id" FROM "flat_scope_fb4" WHERE "card.id" IS NOT NULL)),
"batch_parent_flat_4" AS MATERIALIZED (SELECT DISTINCT "fi5_b6"."id" AS "id" FROM "flat_scope_fb4" "fi5" LEFT JOIN "reachable_Card_0" "fi5_b6" ON "fi5_b6"."id" = fi5."card.id"),
"flat_base_fi5_fb9" AS MATERIALIZED (SELECT "fi5_ct7"."card.id" AS "__parent_id", "fi5_ct7"."id" AS "__item_id", "fi5_ct7".* FROM "authorized_Face" "fi5_ct7" JOIN "batch_parent_flat_4" "fi5_b6" ON TRUE WHERE "fi5_ct7"."card.id" = "fi5_b6"."id"),
"flat_unique_fi5_fb9" AS MATERIALIZED (SELECT DISTINCT ON ("__parent_id", "__item_id") * FROM "flat_base_fi5_fb9" ORDER BY "__parent_id", "__item_id"),
"flat_selected_fi5_fb9" AS MATERIALIZED (SELECT * FROM (SELECT "__selected_source".*,  row_number() OVER (PARTITION BY "__parent_id" ORDER BY "__item_id") AS "__selected_ordinal"  FROM (SELECT * FROM "flat_unique_fi5_fb9") AS "__selected_source") AS "__selected" WHERE  "__selected_ordinal" -  $5  BETWEEN 1 AND  $6),
"flat_rows_fi5_fb9" AS MATERIALIZED (SELECT "fi5_fi10"."__parent_id", "fi5_fi10"."__item_id", fi5_fi10."id" AS "id", fi5_fi10."name" AS "name", fi5_fi10."entity" AS "entity" FROM "flat_selected_fi5_fb9" "fi5_fi10" ),
"flat_counts_fi5_fb9" AS MATERIALIZED (SELECT "__parent_id", count(*)::int AS "__total" FROM "flat_unique_fi5_fb9" GROUP BY "__parent_id"),
"flat_items_fi5_fb9" AS MATERIALIZED (WITH "__item_group" AS MATERIALIZED (SELECT "__parent_id", COALESCE(json_agg(row_to_json("__item") ORDER BY "__item"."__item_id")  , '[]'::json) AS "__items"  FROM "flat_rows_fi5_fb9" AS "__item" GROUP BY "__parent_id") , "__matched" AS MATERIALIZED (SELECT "__parent_id", count(*)::int AS "__matched" FROM "flat_rows_fi5_fb9" GROUP BY "__parent_id") SELECT "__parents"."__parent_id", COALESCE("__item_group"."__items", '[]'::json) AS "__items", COALESCE("__matched"."__matched", 0) AS "__matched" FROM (SELECT "__parent_id" FROM "__item_group" UNION SELECT "__parent_id" FROM "__matched") AS "__parents" LEFT JOIN "__item_group" ON "__item_group"."__parent_id" = "__parents"."__parent_id" LEFT JOIN "__matched" ON "__matched"."__parent_id" = "__parents"."__parent_id"),
"flat_rows_fb4" AS MATERIALIZED (SELECT DISTINCT ON ("fi5"."__parent_id", "fi5"."__item_id") "fi5"."__parent_id", "fi5"."__item_id", fi5."id" AS "id", fi5."name" AS "name", fi5."entity" AS "entity", 'Card' AS "card__entity", fi5_b6."id" AS "card__id", fi5_b6."name" AS "card__name", COALESCE("fi5_bc11"."__items", '[]'::json) AS "card__faces", COALESCE("fi5_bc11"."__matched", 0) AS "card__faces__matched", COALESCE("fi5_bn12"."__total", 0) AS "card__faces__total" FROM "flat_base_fb4" "fi5" LEFT JOIN "reachable_Card_0" "fi5_b6" ON "fi5_b6"."id" = fi5."card.id"LEFT JOIN "flat_items_fi5_fb9" "fi5_bc11" ON "fi5_bc11"."__parent_id" = "fi5_b6"."id" LEFT JOIN "flat_counts_fi5_fb9" "fi5_bn12" ON "fi5_bn12"."__parent_id" = "fi5_b6"."id"),
"flat_counts_fb4" AS MATERIALIZED (SELECT "__parent_id", count(*)::int AS "__total" FROM "flat_rows_fb4" GROUP BY "__parent_id"),
"flat_items_fb4" AS MATERIALIZED (WITH "__item_group" AS MATERIALIZED (SELECT "__parent_id", COALESCE(json_agg(row_to_json("__item") ORDER BY "__item"."__ordinal")  FILTER (WHERE  "__ordinal" - $3 BETWEEN 1 AND $4 ), '[]'::json) AS "__items"  FROM ( SELECT  row_number() OVER ( PARTITION BY "__parent_id" ORDER BY "__child"."__item_id")  AS "__ordinal", "__child".*  FROM "flat_rows_fb4" AS "__child")  AS "__item" GROUP BY "__parent_id") , "__matched" AS MATERIALIZED (SELECT "__parent_id", count(*)::int AS "__matched" FROM "flat_rows_fb4" GROUP BY "__parent_id") SELECT "__parents"."__parent_id", COALESCE("__item_group"."__items", '[]'::json) AS "__items", COALESCE("__matched"."__matched", 0) AS "__matched" FROM (SELECT "__parent_id" FROM "__item_group" UNION SELECT "__parent_id" FROM "__matched") AS "__parents" LEFT JOIN "__item_group" ON "__item_group"."__parent_id" = "__parents"."__parent_id" LEFT JOIN "__matched" ON "__matched"."__parent_id" = "__parents"."__parent_id") SELECT t."id" AS "id", COALESCE("bc13"."__items", '[]'::json) AS "printings", COALESCE("bc13"."__matched", 0) AS "printings__matched", COALESCE("bn14"."__total", 0) AS "printings__total" FROM "batch_selected_rows_0" "t" LEFT JOIN "flat_items_fb4" "bc13" ON "bc13"."__parent_id" = "t"."id" LEFT JOIN "flat_counts_fb4" "bn14" ON "bn14"."__parent_id" = "t"."id"  